// Purchase references (/purchase/<ref>): 128 random bits generated by the
// database, base64url. Not a credential on its own: every purchase route
// also requires this browser's session cookie.

const REF_PATTERN = /^[A-Za-z0-9_-]{22}$/;

export function isPublicRef(value: string): boolean {
  return REF_PATTERN.test(value);
}
